module parity_8bit (
    input [7:0] in,
    output out
);
    wire w1, w2, w3, w4, w5, w6, w7;

    xor (w1, in[1], in[0]);
    xor (w2, in[2], in[3]);
    nand (w3, w1, w2);

    xor (w4, in[5], in[4]);
    nand (w5, in[7], in[6]);
    xor (w6, w4, w5);

    xor (w7, w3, w6);
    not (out, w7);
endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

    wire not_val_1_0, not_val_0_0, and1, and2, and3, or1;

    not(not_val_1_0, sel[0]);
    not(not_val_0_0, in[0]);

    and(and1, sel[1], in[1]);
    and(and2, not_val_1_0, in[2]);
    and(and3, not_val_1_0, not_val_0_0);

    or(or1, and1, and2);
    xor(out, or1, and3);

endmodule

module majority (
    input a, b, c,
    output out
);

    wire not_val_0, not_val_1, not_val_2;
    wire and1_out, and2_out, and3_out;
    wire or1_out;

    // Inverters
    not (not_val_0, a);
    not (not_val_1, b);
    not (not_val_2, c);

    // AND gates
    and (and1_out, not_val_2, b);
    and (and2_out, not_val_1, a);
    and (and3_out, c, not_val_0);

    // OR gates
    or (or1_out, and1_out, and2_out);

    // Final OR gate for output
    or (out, or1_out, and3_out);

endmodule

module bin_to_gray (
    input [3:0] binary,
    output [3:0] gray
);
    assign gray[0] = binary[0] ^ binary[1];
    assign gray[1] = binary[1] ^ binary[2];
    assign gray[2] = binary[2] ^ binary[3];
    assign gray[3] = binary[3] ^ binary[0];
endmodule

module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);

    wire [3:0] xor_res;
    wire [3:0] and_res;
    wire or_res;
    wire nand_res;

    assign xor_res = a ^ b;
    assign and_res = a & b;
    assign or_res = |(and_res | xor_res);
    assign nand_res = ~(or_res);
    assign equal = ~nand_res;

endmodule

module decoder_2to4 (
    input [1:0] in,
    output [3:0] out
);
    assign out[0] = ~in[1] & ~in[0];
    assign out[1] = ~in[1] &  in[0];
    assign out[2] =  in[1] & ~in[0];
    assign out[3] =  in[1] &  in[0];
endmodule

module priority_encoder (
    input [3:0] in,
    output reg [1:0] code
);

    always @(*) begin
        code[1] = (~in[2] & in[3]) | (in[1] & in[0]);
        code[0] = in[1] | (in[0] & (~in[2]));
    end

endmodule

module fsm_3state (
    input clk, reset,
    output [1:0] state
);

    wire not_val_0;
    wire not_val_1;
    wire and_0, and_1;
    wire or_0, dff_0_out, dff_1_out;

    // Inverters
    not u_not_0 (not_val_0, clk);
    not u_not_1 (not_val_1, reset);

    // AND gates
    and u_and_0 (and_0, not_val_0, reset);
    and u_and_1 (and_1, clk, not_val_1);

    // OR gate
    or u_or_0 (or_0, and_0, dff_1_out);

    // D Flip-flops
    DFF dff_0 (
        .C(clk),
        .D(and_1),
        .Q(dff_0_out)
    );

    DFF dff_1 (
        .C(reset),
        .D(or_0),
        .Q(dff_1_out)
    );

    // Final output assignments
    assign state[0] = ~dff_0_out;
    assign state[1] = dff_1_out;

endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);
    wire not_val_0, not_val_1;
    wire and1, and2, and3, and4, and5, and6, and_or;
    wire or1, or2, or3;

    not u1 (not_val_0, clk);
    not u2 (not_val_1, reset);

    and u3 (and1, clk, not_val_1);
    and u4 (and2, not_val_0, reset);
    and u5 (and3, clk, reset);

    or u6 (or1, and1, and2);
    and u7 (and4, or1, and3);

    or u8 (or2, not_val_0, not_val_1);
    and u9 (and5, or2, and4);

    or u10 (or3, clk, reset);
    and u11 (and6, or3, and5);

    assign light[0] = and1;
    assign light[1] = and4;
    assign light[2] = and6;
endmodule

module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

    wire q0, q1;
    wire nq0, nq1;
    wire a1, a2, a3, a4, a5, a6, a7, a8;

    // Flip-flops
    S_DFF_PP0 ff0 (
        .C(clk),
        .D(reset),
        .R(down_request),
        .Q(q0)
    );

    S_DFF_PP0 ff1 (
        .C(clk),
        .D(q0),
        .R(down_request),
        .Q(q1)
    );

    assign nq0 = ~q0;
    assign nq1 = ~q1;

    // Logic gates
    assign a1 = nq0 & nq1;
    assign a2 = q0 & nq1;
    assign a3 = nq0 & q1;
    assign a4 = q0 & q1;
    assign a5 = up_request & a1;
    assign a6 = up_request & a2;
    assign a7 = up_request & a3;
    assign a8 = up_request & a4;

    assign state[0] = a6 | a8;
    assign state[1] = a5 | a7;

endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

    wire dffe1_q, dffe2_q;
    wire and1_out, and2_out, and3_out, and4_out, or1_out, or2_out;
    wire mux_out;

    // First D flip-flop
    DFFE dffe1 (
        .D(and1_out),
        .C(clk),
        .E(1'b1),
        .R(1'b0),
        .Q(dffe1_q)
    );

    // Second D flip-flop
    DFFE dffe2 (
        .D(and2_out),
        .C(clk),
        .E(1'b1),
        .R(1'b0),
        .Q(dffe2_q)
    );

    // Logic gates
    assign and1_out = reset & dffe1_q;
    assign and2_out = coin_inserted & dffe2_q;
    assign and3_out = item_selected & coin_inserted;
    assign and4_out = reset & dffe2_q;
    assign or1_out = and1_out | and3_out;
    assign or2_out = or1_out | and4_out;

    // 2-to-1 Multiplexer
    assign mux_out = (clk) ? or2_out : 1'b0;

    // Outputs
    assign state[0] = dffe1_q;
    assign state[1] = mux_out;

endmodule

module power (
    input signed [7:0] in_0,
    input signed [3:0] in_1,
    output signed [15:0] out
);
    assign out = in_0 ** in_1;
endmodule

module log2_int (
    input signed [15:0] in_0,
    output signed [7:0] out
);

    wire [15:0] not_val_0;  // Wires for NOT gates
    wire [7:0] intermed_0; // Intermediate values for AND/OR logic
    wire [7:0] intermed_1;

    // NOT gates
    assign not_val_0[0] = ~in_0[0];
    assign not_val_0[1] = ~in_0[1];
    assign not_val_0[2] = ~in_0[2];
    assign not_val_0[3] = ~in_0[3];
    assign not_val_0[4] = ~in_0[4];
    assign not_val_0[5] = ~in_0[5];
    assign not_val_0[6] = ~in_0[6];
    assign not_val_0[7] = ~in_0[7];
    assign not_val_0[8] = ~in_0[8];
    assign not_val_0[9] = ~in_0[9];
    assign not_val_0[10] = ~in_0[10];
    assign not_val_0[11] = ~in_0[11];
    assign not_val_0[12] = ~in_0[12];
    assign not_val_0[13] = ~in_0[13];
    assign not_val_0[14] = ~in_0[14];
    assign not_val_0[15] = ~in_0[15];

    // Logic for out[0]
    assign intermed_0[0] = in_0[0] & in_0[1];
    assign intermed_1[0] = intermed_0[0] | not_val_0[2];
    assign out[0] = intermed_1[0] ^ in_0[3];

    // Logic for out[1]
    assign intermed_0[1] = in_0[4] & in_0[5];
    assign intermed_1[1] = intermed_0[1] | not_val_0[6];
    assign out[1] = intermed_1[1] ^ in_0[7];

    // Logic for out[2]
    assign intermed_0[2] = in_0[8] & in_0[9];
    assign intermed_1[2] = intermed_0[2] | not_val_0[10];
    assign out[2] = intermed_1[2] ^ in_0[11];

    // Logic for out[3]
    assign intermed_0[3] = in_0[12] & in_0[13];
    assign intermed_1[3] = intermed_0[3] | not_val_0[14];
    assign out[3] = intermed_1[3] ^ in_0[15];

    // Logic for out[4] to out[7]
    assign out[4] = in_0[0] & not_val_0[1];
    assign out[5] = in_0[2] | not_val_0[3];
    assign out[6] = in_0[4] ^ not_val_0[5];
    assign out[7] = in_0[6] & not_val_0[7];

endmodule

module add_8bit (
    input signed [7:0] a, b,
    output signed [8:0] out
);
    wire [8:0] sum;
    wire carry;

    assign {carry, sum} = a + b;

    assign out = sum;
endmodule

module subtract_8bit (
    input signed [7:0] a, b,
    output signed [8:0] diff
);

    wire [7:0] xnor_1, xnor_2, and_1, and_2, or_1, nand_1;

    assign xnor_1 = a ~^ b;
    assign xnor_2 = b ~^ a;

    assign and_1 = a & xnor_1;
    assign and_2 = b & xnor_2;

    assign or_1 = and_1 | and_2;
    assign nand_1 = ~(or_1 & a);

    assign diff = {nand_1, or_1, and_1, xnor_1};

endmodule

module bitwise_ops (
    input [7:0] a, b,
    output [7:0] and_out,
    output [7:0] or_out,
    output [7:0] xor_out
);
    assign and_out[0] = a[0] & b[0];
    assign and_out[1] = a[1] | b[1];
    assign and_out[2] = ~(a[2] & b[2]);
    assign and_out[3] = a[3] ^ b[3];
    assign and_out[4] = a[4] ~^ b[4];
    assign and_out[5] = a[5];
    assign and_out[6] = b[6];
    assign and_out[7] = ~(a[7] | b[7]);

    assign or_out[0] = a[2] & b[6];
    assign or_out[1] = a[3] | b[5];
    assign or_out[2] = ~(a[1] ^ b[4]);
    assign or_out[3] = a[7] & b[3];
    assign or_out[4] = a[6] | ~(b[2]);
    assign or_out[5] = ~(a[5] | b[1]);
    assign or_out[6] = a[4] ~^ b[0];
    assign or_out[7] = ~(a[0] & b[7]);

    assign xor_out[0] = and_out[0] & or_out[0];
    assign xor_out[1] = and_out[1] ^ or_out[1];
    assign xor_out[2] = and_out[2] | or_out[2];
    assign xor_out[3] = ~(and_out[3] & or_out[3]);
    assign xor_out[4] = and_out[4] ~^ or_out[4];
    assign xor_out[5] = and_out[5] | ~(or_out[5]);
    assign xor_out[6] = ~(and_out[6] | or_out[6]);
    assign xor_out[7] = and_out[7] ^ or_out[7];
endmodule

module left_shift (
    input [7:0] in,
    input [2:0] shift,
    output [7:0] out
);
    assign out[0] = (shift[0] & in[0]) | (~shift[0] & in[1]);
    assign out[1] = (shift[0] & in[2]) | (~shift[0] & in[3]);
    assign out[2] = (shift[0] & in[4]) | (~shift[0] & in[5]);
    assign out[3] = (shift[0] & in[6]) | (~shift[0] & in[7]);
    assign out[4] = (shift[1] & in[0]) | (~shift[1] & in[2]);
    assign out[5] = (shift[1] & in[4]) | (~shift[1] & in[6]);
    assign out[6] = (shift[2] & in[1]) | (~shift[2] & in[5]);
    assign out[7] = (shift[2] & in[3]) | (~shift[2] & in[7]);
endmodule

module bitwise_not (
    input [7:0] in,
    output [7:0] out
);
    assign out[0] = ~in[1];
    assign out[1] = ~in[0];
    assign out[2] = ~in[3];
    assign out[3] = ~in[2];
    assign out[4] = ~in[5];
    assign out[5] = ~in[4];
    assign out[6] = ~in[7];
    assign out[7] = ~in[6];
endmodule

module rotate_left (
    input [7:0] in,
    input [2:0] shift,
    output [7:0] out
);

    assign out[0] = ~in[0] & ~shift[0] | in[3] & shift[1];
    assign out[1] = (in[2] | shift[1]) & ~shift[2];
    assign out[2] = in[1] ^ (shift[0] | shift[2]);
    assign out[3] = ~(in[5] & shift[1]) | in[4];
    assign out[4] = in[7] & (~shift[0] | shift[1]);
    assign out[5] = (in[6] | shift[2]) & ~shift[1];
    assign out[6] = in[1] | (~in[5] & shift[0]);
    assign out[7] = ~(in[7] ^ shift[2]);

endmodule

module relu (
    input signed [15:0] in_0,
    output signed [15:0] out);

    assign out[0] = in_0[6] & ~in_0[15] & ~in_0[7];
    assign out[1] = ~in_0[8] & in_0[9] & ~in_0[6];
    assign out[2] = in_0[10] & in_0[13] & ~in_0[11];
    assign out[3] = in_0[12] & in_0[1] & ~in_0[2];
    assign out[4] = in_0[3] & ~in_0[4] & in_0[5];
    assign out[5] = ~in_0[6] & in_0[7] & ~in_0[8];
    assign out[6] = in_0[9] & ~in_0[10] & in_0[11];
    assign out[7] = in_0[12] & ~in_0[13] & in_0[14];
    assign out[8] = in_0[10] & in_0[11] & ~in_0[3];
    assign out[9] = ~in_0[14] & in_0[15] & in_0[0];
    assign out[10] = in_0[4] & in_0[5] & ~in_0[6];
    assign out[11] = ~in_0[7] & in_0[8] & ~in_0[9];
    assign out[12] = ~in_0[0] & in_0[1] & in_0[2];
    assign out[13] = in_0[3] & ~in_0[12] & in_0[13];
    assign out[14] = in_0[8] & ~in_0[9] & in_0[10];
    assign out[15] = 1'b0;

endmodule

module caesar_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);

assign data_out[0] = ~data_in[0];
assign data_out[1] = data_in[1] ^ data_in[2];
assign data_out[2] = (data_in[2] & data_in[3]) | (~data_in[4]);
assign data_out[3] = ((data_in[3] | data_in[4]) & data_in[5]) ^ data_in[6];
assign data_out[4] = (data_in[4] & ~data_in[5]) | (data_in[5] & data_in[6]);
assign data_out[5] = ~(data_in[5] ^ data_in[6]);
assign data_out[6] = (data_in[6] & data_in[7]) ^ data_in[0];
assign data_out[7] = (data_in[7] | data_in[0]) & data_in[1];

endmodule

module modular_add_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);
    assign data_out[0] = ~data_in[0] | data_in[1];
    assign data_out[1] = (data_in[2] & data_in[3]) | data_in[1];
    assign data_out[2] = data_in[4] ^ data_in[5];
    assign data_out[3] = (data_in[6] & (data_in[5] | data_in[3])) ^ data_in[4];
    assign data_out[4] = ~(data_in[7] & data_in[6]) | data_in[3];
    assign data_out[5] = ((data_in[6] | data_in[7]) & data_in[2]) ^ data_in[4];
    assign data_out[6] = ~((data_in[5] & data_in[1]) | (data_in[2] ^ data_in[3]));
    assign data_out[7] = (data_in[7] & (~data_in[6] | data_in[4])) ^ data_in[5];
endmodule

module feistel_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);
    parameter KEY = 4'b1010;

    assign data_out[0] = data_in[0] ^ data_in[4];
    assign data_out[1] = data_in[1] ^ data_in[5];
    assign data_out[2] = data_in[2] ^ data_in[6];
    assign data_out[3] = data_in[3] ^ data_in[7];
    assign data_out[4] = data_in[0] ^ data_in[4];
    assign data_out[5] = data_in[1] ^ data_in[5];
    assign data_out[6] = data_in[2] ^ data_in[6];
    assign data_out[7] = data_in[3] ^ data_in[7];

endmodule

module clock_div2 (
    input clk,
    input rst,
    output clk_out
);
    wire q;

    // Flip-flop instantiation
    S_SDFF_PP0_ u1 (
        .C(clk),
        .D(rst),
        .R(rst),
        .Q(q)
    );

    // Inverter
    assign clk_out = ~q;
endmodule

module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);

    wire n0, n1, n2, n3, n4, n5, n6, n7, n8, n9, n10;

    assign n0 = ~(a[0] & b[0]);
    assign n1 = a[1] | b[1];
    assign n2 = a[2] ^ b[2];
    assign n3 = ~(a[3] | b[3]);
    assign n4 = n0 & n1;
    assign n5 = n2 | n3;
    assign n6 = ~(n4 | n5);
    assign n7 = n0 ^ n5;
    assign n8 = n1 & n3;
    assign n9 = ~(n6 & n7);
    assign n10 = n8 | n9;

    assign gt = n6;
    assign eq = n7;
    assign lt = n10;

endmodule

module decoder_2to4 (
    input  [1:0] in,
    input        enable,
    output [3:0] out
);

    wire not_val0_0, not_val0_1, not_val1;
    wire and_0, and_1, and_2, and_3;

    // Negations
    assign not_val0_0 = ~in[0];
    assign not_val0_1 = ~in[1];
    assign not_val1 = ~enable;

    // AND gates
    assign and_0 = not_val0_0 & not_val0_1;
    assign and_1 = not_val0_0 & in[1];
    assign and_2 = in[0] & not_val1;
    assign and_3 = enable & in[0];

    // Output assignments
    assign out[0] = and_0;
    assign out[1] = and_1;
    assign out[2] = and_2;
    assign out[3] = and_3;

endmodule

module decoder3to8(input [2:0] in, input enable, output [7:0] out);
  wire n0, n1, n2, n3, n4, n5, n6, n7;

  assign n0 = ~in[0];
  assign n1 = in[1] & n0;
  assign n2 = ~in[2];
  assign n3 = n1 & n2;
  assign n4 = enable | in[0];
  assign n5 = ~(in[1] | enable);
  assign n6 = n4 & n5;
  assign n7 = n6 | n3;

  assign out[0] = n3;
  assign out[1] = n6;
  assign out[2] = n7;
  assign out[3] = 0;
  assign out[7:4] = 4'b0000;
endmodule

module demux_1to2 (
    input  in,
    input  sel,
    output out0,
    output out1
);

    wire and_out, nand_out;

    assign and_out = in & sel;
    assign nand_out = ~(in & sel);

    assign out1 = and_out;
    assign out0 = nand_out;

endmodule

module demux_1to4 (
    input        in,
    input  [1:0] sel,
    output       out0,
    output       out1,
    output       out2,
    output       out3
);
    wire and1_out, and2_out, not1_out;

    assign and1_out = in & sel[0];
    assign and2_out = in & sel[1];
    assign not1_out = ~and2_out;

    assign out0 = not1_out;
    assign out1 = and1_out;
    assign out2 = 1'b0;
    assign out3 = 1'b0;
endmodule

module gray_counter8(
    input wire clk,
    input wire rst,
    output wire [7:0] count
);

    wire n_val_1, n0, n1, n2, n3, n4, n5, n6, n7;
    wire q_0, q_1, q_2, q_3, q_4, q_5, q_6, q_7;

    // Inverter
    assign n_val_1 = ~rst;

    // Flip-flops
    reg FF_0, FF_1, FF_2, FF_3, FF_4, FF_5, FF_6, FF_7;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            FF_0 <= 0;
            FF_1 <= 0;
            FF_2 <= 0;
            FF_3 <= 0;
            FF_4 <= 0;
            FF_5 <= 0;
            FF_6 <= 0;
            FF_7 <= 0;
        end else begin
            FF_0 <= n0;
            FF_1 <= n1;
            FF_2 <= n2;
            FF_3 <= n3;
            FF_4 <= n4;
            FF_5 <= n5;
            FF_6 <= n6;
            FF_7 <= n7;
        end
    end

    assign q_0 = FF_0;
    assign q_1 = FF_1;
    assign q_2 = FF_2;
    assign q_3 = FF_3;
    assign q_4 = FF_4;
    assign q_5 = FF_5;
    assign q_6 = FF_6;
    assign q_7 = FF_7;

    // Logic gates connecting FF and outputs
    assign n0 = q_7 ^ n_val_1;
    assign n1 = q_0 & n_val_1;
    assign n2 = q_1 | n_val_1;
    assign n3 = q_2 & ~rst;
    assign n4 = q_3 ^ rst;
    assign n5 = q_4 | rst;
    assign n6 = q_5 & n_val_1;
    assign n7 = q_6 ^ rst;

    // Outputs
    assign count[0] = q_0;
    assign count[1] = q_1;
    assign count[2] = q_2;
    assign count[3] = q_3;
    assign count[4] = q_4;
    assign count[5] = q_5;
    assign count[6] = q_6;
    assign count[7] = q_7;

endmodule

module johnson_counter4 (
    input clk,
    input rst,
    output [3:0] q
);

    wire not_val_0;
    wire dff0_q, dff1_q, dff2_q, dff3_q;

    assign not_val_0 = ~clk;

    // Flip-Flop 0
    always @(posedge clk or posedge not_val_0)
        if (not_val_0)
            dff0_q <= 0;
        else
            dff0_q <= rst;

    // Flip-Flop 1
    always @(posedge clk or posedge not_val_0)
        if (not_val_0)
            dff1_q <= 0;
        else
            dff1_q <= dff0_q;

    // Flip-Flop 2
    always @(posedge clk or posedge not_val_0)
        if (not_val_0)
            dff2_q <= 0;
        else
            dff2_q <= dff1_q;

    // Flip-Flop 3
    always @(posedge clk or posedge not_val_0)
        if (not_val_0)
            dff3_q <= 0;
        else
            dff3_q <= dff2_q;

    assign q = {dff3_q, dff2_q, dff1_q, dff0_q};

endmodule

module piso_8bit(
    input clk,
    input rst,
    input load,
    input [7:0] pin,
    output sout
);

    wire not_val_0;
    wire and_val_1_val_2;
    wire [7:0] mux_out;

    // Inverters
    not(not_val_0, clk);

    // AND gate
    and(and_val_1_val_2, rst, load);

    // Multiplexers for each bit of pin
    assign mux_out[0] = and_val_1_val_2 ? pin[0] : not_val_0;
    assign mux_out[1] = and_val_1_val_2 ? pin[1] : not_val_0;
    assign mux_out[2] = and_val_1_val_2 ? pin[2] : not_val_0;
    assign mux_out[3] = and_val_1_val_2 ? pin[3] : not_val_0;
    assign mux_out[4] = and_val_1_val_2 ? pin[4] : not_val_0;
    assign mux_out[5] = and_val_1_val_2 ? pin[5] : not_val_0;
    assign mux_out[6] = and_val_1_val_2 ? pin[6] : not_val_0;
    assign mux_out[7] = and_val_1_val_2 ? pin[7] : not_val_0;

    // Flip-flops for each bit
    wire [7:0] ff_out;
    reg [7:0] ff_reg;

    always @(posedge clk or negedge clk) begin
        ff_reg <= mux_out;
    end

    assign ff_out = ff_reg;

    // Output logic
    assign sout = ff_out[7];

endmodule

module priority_encoder_4to2 (
    input  [3:0] in,
    output [1:0] out,
    output       valid
