    assign not_0 = ~in[2];
    assign and_0 = in[1] & not_0;
    assign or_0  = in[3] | and_0;
    assign and_1 = in[0] & in[2];
    assign or_1  = and_1 | in[3];

    assign out[1] = or_0;
    assign out[0] = or_1;
    assign valid    = in[1] & in[0];

endmodule

module ring_counter4 (
    input clk,
    input rst,
    output [3:0] q
);

    wire d_0, q_0, q_n_0;
    wire d_1, q_1, q_n_1;
    wire d_2, q_2, q_n_2;

    // Flip-flop 0
    assign d_0 = clk & rst;
    SDFF ff_0 (
        .C(rst),
        .D(d_0),
        .R(clk),
        .Q(q_0),
        .Q_(q_n_0)
    );

    // Flip-flop 1
    assign d_1 = q_0;
    SDFF ff_1 (
        .C(rst),
        .D(d_1),
        .R(clk),
        .Q(q_1),
        .Q_(q_n_1)
    );

    // Flip-flop 2
    assign d_2 = q_1;
    SDFF ff_2 (
        .C(rst),
        .D(d_2),
        .R(clk),
        .Q(q_2),
        .Q_(q_n_2)
    );

    // Output assignments
    assign q[0] = q_0;
    assign q[1] = q_n_1;
    assign q[2] = q_2;
    assign q[3] = q_n_2;

endmodule

module sipo_8bit(
    input clk,
    input rst,
    input sin,
    output [7:0] pout
);

    wire ff_0_out, ff_1_out, ff_2_out, ff_3_out, ff_4_out, ff_5_out, ff_6_out, ff_7_out;

    // Flip-flop instantiations
    sdff_pp0 ff_0 (.D(sin), .C(clk), .R(rst), .Q(ff_0_out));
    sdff_pp0 ff_1 (.D(ff_0_out), .C(clk), .R(rst), .Q(ff_1_out));
    sdff_pp0 ff_2 (.D(ff_1_out), .C(clk), .R(rst), .Q(ff_2_out));
    sdff_pp0 ff_3 (.D(ff_2_out), .C(clk), .R(rst), .Q(ff_3_out));
    sdff_pp0 ff_4 (.D(ff_3_out), .C(clk), .R(rst), .Q(ff_4_out));
    sdff_pp0 ff_5 (.D(ff_4_out), .C(clk), .R(rst), .Q(ff_5_out));
    sdff_pp0 ff_6 (.D(ff_5_out), .C(clk), .R(rst), .Q(ff_6_out));
    sdff_pp0 ff_7 (.D(ff_6_out), .C(clk), .R(rst), .Q(ff_7_out));

    // Outputs mapping
    assign pout = {ff_7_out, ff_6_out, ff_5_out, ff_4_out, ff_3_out, ff_2_out, ff_1_out, ff_0_out};

endmodule

module siso_8bit(
    input clk,
    input rst,
    input sin,
    output sout
);

    wire q0, q1, q2, q3, q4;

