  assign d0 = n_val_0 ^ reset;
  assign d1 = n_val_1 & q0;
  assign d2 = q1 | q3;
  assign d3 = q0 & q2;

  // D Flip-Flops
  always @(posedge clk) q0 <= d0;
  always @(posedge clk) q1 <= d1;
  always @(posedge clk) q2 <= d2;
  always @(posedge clk) q3 <= d3;

  // Output
