    // D flip-flop logic
    dff0_q = clk & ~reset;
    dff1_q = clk | dff0_q;
    dff2_q = dff0_q ^ dff1_q;
    dff3_q = ~(dff1_q & dff2_q);

    // Assigning to outputs
    q[0] = ~dff0_q;
