module TopModule (
  input clk,
  input reset,
  output reg [3:0] q
);

  wire dff1_q, dff2_q, dff3_q;
  wire and1_out, and2_out;
  wire or1_out, or2_out, or3_out;
  wire not1_out;

  // NOT Gate
  assign not1_out = ~clk;

  // AND Gates
  assign and1_out = clk & reset;
  assign and2_out = not1_out & reset;

  // Flip-Flops
  S_SDFF_PP1_ dff1 (.C(clk), .D(and1_out), .R(1'b0), .Q(dff1_q));
  S_SDFF_PP0_ dff2 (.C(not1_out), .D(and2_out), .R(1'b0), .Q(dff2_q));
  S_SDFF_PP0_ dff3 (.C(reset), .D(dff2_q), .R(1'b0), .Q(dff3_q));

  // OR Gates
  assign or1_out = dff1_q | dff2_q;
  assign or2_out = or1_out | dff3_q;
  assign or3_out = or2_out | dff3_q;

  // Output Assignment
  always @(*) begin
    q[0] = dff1_q;
    q[1] = dff2_q;
    q[2] = dff3_q;
    q[3] = or3_out;
  end

endmodule

