  // Inverters
  assign not1_out = ~clk;
  assign not2_out = ~dff1_q;

  // AND gates
  assign and1_out = train_valid & train_taken;
  assign and2_out = dff2_q & not1_out;
  assign and3_out = not2_out & and1_out;

  // OR gates
  assign or1_out = clk | areset;
  assign or2_out = and3_out | and2_out;

  // D flip-flops
  S_DFFE_PP1P_ dff1 (.C(clk), .D(or1_out), .Q(dff1_q));
  S_DFFE_PP0P_ dff2 (.C(areset), .D(or2_out), .Q(dff2_q));

