module TopModule (
  input clk,
  input aresetn,
  input x,
  output reg z
);

  wire dff1_q;
  wire dff2_q;
  wire and_out;

  // D Flip-Flop 1
  reg dff1_d;
  always @(posedge clk or posedge x) begin
    if (x)
      dff1_d <= 1'b0;
    else
      dff1_d <= aresetn;
  end
  assign dff1_q = dff1_d;

  // AND gate
  assign and_out = dff1_q & aresetn;

