module TopModule (
  input clk,
  input reset,
  input w,
  output z
);

  wire not_val_0, not_val_1, not_val_2;
  wire q1, q2, d1, d2;
  wire and1, and2, and3, and4, and5;
  wire or1, or2, or3, or4, or5;

  // Negation of inputs
  not (not_val_0, clk);
  not (not_val_1, reset);
  not (not_val_2, w);

  // Flip-flop 1
  assign d1 = or1;
  S_SDFF_PP0 ff1 (
    .D(d1),
    .C(clk),
    .R(1'b0),
    .Q(q1)
  );

  // Flip-flop 2
  assign d2 = or2;
  S_SDFF_PP0 ff2 (
    .D(d2),
    .C(q1),
    .R(1'b0),
    .Q(q2)
  );

  // AND gates
  and (and1, reset, not_val_0);
  and (and2, q1, w);
  and (and3, not_val_1, q1);
  and (and4, q2, not_val_2);
  and (and5, and2, and3);

  // OR gates
  or (or1, and1, not_val_1);
  or (or2, and4, and5);
  or (or3, q1, not_val_2);
  or (or4, q2, or3);
  or (or5, and1, or4);

  // Final output
  assign z = or5;

endmodule

