  assign and_1 = clk & y[0];
  assign and_2 = not_val_0 & not_val_2_1;
  assign and_3 = y[2] & not_val_2_0;

  assign or_1 = and_1 | and_2;
  assign nand_1 = ~(or_1 & and_3);

  assign xor_1 = nand_1 ^ x;

