  assign q1 = dff1_q;

  // S_DFF_PP2
  reg dff2_q;
  always @(posedge bump_left or posedge areset) begin
    if (areset)
      dff2_q <= 1'b0;
    else
      dff2_q <= n6;
  end
  assign q2 = dff2_q;

  // Logic
  assign n1 = bump_left & areset;
  assign n2 = bump_right | q0;
  assign n3 = ~bump_left;

  assign n4 = q0 & bump_right;
  assign n5 = n4 & n3;

  assign n6 = q1 | bump_left;
  assign n7 = q2 & ground;

  assign n8 = n6 ^ n7;
  assign n9 = n8 & bump_right;
  assign n10 = n9 | clk;

  assign walk_left = n5;
  assign walk_right = n10;
  assign aaah = n2;

