module TopModule (
  input d,
  input done_counting,
  input ack,
  input [9:0] state, // 10-bit one-hot current state
  output B3_next,
  output S_next,
  output S1_next,
  output Count_next,
  output Wait_next,
  output done,
  output counting,
  output shift_ena
);

  assign B3_next = d & state[8] & state[7];
  assign S_next = done_counting & state[9] & ~ack;
  assign S1_next = state[0] | (d & state[1]);
  assign Count_next = (state[5] & ~state[6]) & (ack | state[4]);
  assign Wait_next = done_counting & (state[4] | state[5]);
  assign done = ack & state[6];
  assign counting = d & (~state[8] | state[7]);
  assign shift_ena = d & state[9] & ack;

endmodule

module adder_32bit(A, B, S, C32);
    input [32:1] A;
    input [32:1] B;
    output [32:1] S;
    output C32;

    wire carry_out_0;
    wire carry_out_1;

    cla_16bit cla_0 (
        .Cin(1'b0),
        .A(A[15:0]),
        .B(B[15:0]),
        .S(S[15:0]),
        .Cout(carry_out_0)
    );

    cla_16bit cla_1 (
        .Cin(carry_out_0),
        .A(A[31:16]),
        .B(B[31:16]),
        .S(S[31:16]),
        .Cout(carry_out_1)
    );

    assign C32 = carry_out_1;
endmodule

module adder_8bit(
    input [7:0] a, b, 
    input cin, 
    output [7:0] sum, 
    output cout
);
    wire [7:0] intermediate_0, intermediate_1;
    wire [7:0] and_result, or_result, xor_result;
    wire not_val_2;

    assign not_val_2 = ~cin;
    assign intermediate_0 = {8{cin}} & a;
    assign intermediate_1 = {8{not_val_2}} & b;
    assign and_result = intermediate_0 & intermediate_1;
    assign or_result = intermediate_0 | intermediate_1;
    assign xor_result = intermediate_0 ^ intermediate_1;
    assign sum = xor_result | or_result;
    assign cout = &and_result;

endmodule

module adder_bcd (
    input  [3:0] A,   // First BCD number (0-9)
    input  [3:0] B,   // Second BCD number (0-9)
    input  Cin,         // Input carry
    output [3:0] Sum,   // BCD sum (0-9)
    output Cout          // Output carry
);

    wire [3:0] sum;
    wire carry;
    wire corr_carry;
    wire [3:0] correction;

    // Binary addition
    assign {carry, sum} = A + B + Cin;

    // Correction logic for BCD addition
    assign corr_carry = carry | (sum[3] & sum[2]) | (sum[3] & sum[1]);
    assign correction = {1'b0, corr_carry, corr_carry, 1'b0};

    // Calculating final BCD result
    assign {Cout, Sum} = {1'b0, sum} + {1'b0, correction};

endmodule

module comparator_3bit (
    input [2:0] A,
    input [2:0] B,
    output A_greater,
    output A_equal,
    output A_less
);

    wire n1, n2, n3, n4, n5, n6, n7, n8, n9;

    // Intermediate gates
    xor (n1, A[0], B[0]);
    xor (n2, A[1], B[1]);
    xor (n3, A[2], B[2]);
    and (n4, A[0], B[0]);
    and (n5, A[1], B[1]);
    and (n6, A[2], B[2]);
    or  (n7, n4, n5);
    and (n8, n7, n3);
    or  (n9, n6, n8);

    // Outputs
    not (A_equal, n7);
    and (A_greater, n2, n9);
    or  (A_less, n1, n9);

endmodule

module comparator_4bit(
    input [3:0] A,   // First 4-bit input operand
    input [3:0] B,   // Second 4-bit input operand
    output A_greater, 
    output A_equal,   
    output A_less     
);

    wire n1, n2, n3, n4, n5, n6, n7, n8, n9, n10;
    wire n11, n12, n13, n14, n15, n16;

    // Intermediate logic
    assign n1 = A[3] & B[3];
    assign n2 = A[2] | B[2];
    assign n3 = A[1] ^ B[1];
    assign n4 = ~A[0];
    assign n5 = B[0] & A[0];
    assign n6 = n1 | n3;

    assign n7 = n2 & n4;
    assign n8 = n3 | n5;
    assign n9 = n7 | n6;

    // Outputs
    assign A_equal = ~(n9 ^ n8);
    assign A_greater = ~(n4 & n6);
    assign A_less = n2 ^ n3;

endmodule

module counter_12 
(
  input rst_n,
  input clk,
  input valid_count,

  output reg [3:0] out
);

  // Signal declarations
  wire dff1_q, dff2_q, dff3_q, dff4_q;
  wire not_val1, and1_out, and2_out;
  wire or1_out, or2_out, or3_out, or4_out;

  // NOT gate for clk
  assign not_val1 = ~clk;

  // First set of AND gates
  assign and1_out = rst_n & not_val1;
  assign and2_out = valid_count & clk;

  // Second level OR gates
  assign or1_out = and1_out | and2_out;

  // D flip-flop instances
  DFFE dff1(.clk(clk), .d(rst_n), .q(dff1_q));  // Flip-flop 1
  DFFE dff2(.clk(clk), .d(dff1_q), .q(dff2_q)); // Flip-flop 2
  DFFE dff3(.clk(rst_n), .d(clk), .q(dff3_q));  // Flip-flop 3
  DFFE dff4(.clk(valid_count), .d(dff3_q), .q(dff4_q)); // Flip-flop 4

  // Final OR gates for out
  assign or2_out = dff2_q | dff3_q;
  assign or3_out = dff1_q | and2_out;
  assign or4_out = or1_out | dff4_q;

  // Output data assignment
  always @(*) begin
    out[0] = or1_out;
    out[1] = or2_out;
    out[2] = or3_out;
    out[3] = or4_out;
  end

endmodule

// D flip-flop module (DFFE)
module DFFE (
  input clk,
  input d,
  output reg q
);
  always @(posedge clk) begin
    q <= d;
  end
endmodule

module edge_detect(
	input clk,
	input rst_n,
	input a,

	output reg rise,
	output reg down
);

	// Internal signals
	wire dff1_q, dff2_q, dff3_q, dff4_q;
	wire and1_out, and2_out, or_out;

	// First D flip-flop
	S_DFF_PN0 dff1 (
		.C(clk),
		.D(a),
		.Q(dff1_q),
		.R(1'b0)
	);

	// Second D flip-flop
	S_DFF_PN0 dff2 (
		.C(clk),
		.D(rst_n),
		.Q(dff2_q),
		.R(1'b0)
	);

	// AND gate
	assign and1_out = dff1_q & dff2_q;

	// OR gate
	assign or_out = and1_out | a;

	// Third D flip-flop
	S_DFF_PN0 dff3 (
		.C(clk),
		.D(or_out),
		.Q(dff3_q),
		.R(1'b0)
	);

	// Fourth D flip-flop
	S_DFF_PN0 dff4 (
		.C(clk),
		.D(dff1_q),
		.Q(dff4_q),
		.R(1'b0)
	);

	// Assign outputs
	always @(*) begin
		rise = dff3_q;
		down = dff4_q;
	end

endmodule

module freq_divbyeven(
    clk,
    rst_n,
    clk_div
);
    input clk;
    input rst_n;
    output clk_div;
    reg clk_div;

    parameter NUM_DIV = 6;

    wire q0, q1, q2, q3;
    wire not_q3, not_val_0, and_0, and_1, or_0, or_1;

    // NOT gates
    assign not_val_0 = ~clk;
    assign not_q3 = ~q3;

    // AND gates
    assign and_0 = clk & rst_n;
    assign and_1 = q1 & not_val_0;

    // OR gates
    assign or_0 = q2 | and_1;
    assign or_1 = q0 | not_q3;

    // Flip-Flops
    always @(posedge clk) begin
        q0 <= and_0;
    end

    always @(posedge clk) begin
        q1 <= or_0;
    end

    always @(posedge clk) begin
        q2 <= q1;
    end

    always @(posedge clk) begin
        q3 <= or_1;
    end

    // Final Output
    assign clk_div = q3;

endmodule

module instr_reg (
    input clk,
    input rst,
    input [1:0] fetch,
    input [7:0] data,
    output [2:0] ins,
    output [4:0] ad1,
    output [7:0] ad2
);
    wire enable;
    wire [4:0] intermediate_bus;
    wire [7:0] intermediate_bus2;

    assign enable = fetch[1] & ~fetch[0];
    assign intermediate_bus = data[4:0];

    SDFFE_PN_ ff0 (.C(clk), .D(rst), .E(enable), .R(1'b0), .Q(intermediate_bus2[0]));
    SDFFE_PN_ ff1 (.C(clk), .D(rst), .E(enable), .R(1'b0), .Q(intermediate_bus2[1]));
    SDFFE_PN_ ff2 (.C(clk), .D(rst), .E(enable), .R(1'b0), .Q(intermediate_bus2[2]));
    SDFFE_PN_ ff3 (.C(clk), .D(rst), .E(enable), .R(1'b0), .Q(intermediate_bus2[3]));
    SDFFE_PN_ ff4 (.C(clk), .D(intermediate_bus[0]), .E(rst), .R(1'b0), .Q(ins[0]));
    SDFFE_PN_ ff5 (.C(clk), .D(intermediate_bus[1]), .E(rst), .R(1'b0), .Q(ins[1]));
    SDFFE_PN_ ff6 (.C(clk), .D(intermediate_bus[2]), .E(rst), .R(1'b0), .Q(ins[2]));
    SDFFE_PN_ ff7 (.C(clk), .D(intermediate_bus[3]), .E(rst), .R(1'b0), .Q(ad1[0]));
    SDFFE_PN_ ff8 (.C(clk), .D(intermediate_bus[4]), .E(rst), .R(1'b0), .Q(ad1[1]));
    SDFFE_PN_ ff9 (.C(clk), .D(intermediate_bus2[4]), .E(rst), .R(1'b0), .Q(ad1[2]));
    SDFFE_PN_ ff10 (.C(clk), .D(intermediate_bus2[5]), .E(rst), .R(1'b0), .Q(ad1[3]));
    SDFFE_PN_ ff11 (.C(clk), .D(intermediate_bus2[6]), .E(rst), .R(1'b0), .Q(ad1[4]));
    SDFFE_PN_ ff12 (.C(clk), .D(intermediate_bus2[7]), .E(rst), .R(1'b0), .Q(ad2[0]));
    SDFFE_PN_ ff13 (.C(clk), .D(intermediate_bus2[0]), .E(rst), .R(1'b0), .Q(ad2[1]));
    SDFFE_PN_ ff14 (.C(clk), .D(intermediate_bus2[1]), .E(rst), .R(1'b0), .Q(ad2[2]));
    SDFFE_PN_ ff15 (.C(clk), .D(intermediate_bus2[2]), .E(rst), .R(1'b0), .Q(ad2[3]));
    SDFFE_PN_ ff16 (.C(clk), .D(intermediate_bus2[3]), .E(rst), .R(1'b0), .Q(ad2[4]));
    SDFFE_PN_ ff17 (.C(clk), .D(intermediate_bus2[4]), .E(rst), .R(1'b0), .Q(ad2[5]));
    SDFFE_PN_ ff18 (.C(clk), .D(intermediate_bus2[5]), .E(rst), .R(1'b0), .Q(ad2[6]));
    SDFFE_PN_ ff19 (.C(clk), .D(intermediate_bus2[6]), .E(rst), .R(1'b0), .Q(ad2[7]));

endmodule

module LFSR (out, clk, rst);
  input clk, rst;
  output reg [3:0] out;

  wire dff1_q, dff2_q, dff3_q;
  wire or_out;

  always @(posedge clk or posedge rst) begin
    out[0] <= dff1_q;
    out[1] <= dff2_q;
    out[2] <= dff3_q;
    out[3] <= or_out;
  end

  // S_DFF_PPO instantiations
  S_DFF_PPO dff1 (.C(clk), .D(rst), .Q(dff1_q));
  S_DFF_PPO dff2 (.C(clk), .D(dff1_q), .Q(dff2_q));
  S_DFF_PPO dff3 (.C(clk), .D(dff2_q), .Q(dff3_q));

  assign or_out = dff1_q | dff3_q;

endmodule

module right_shifter(clk, q, d);  

    input clk;  
    input d;  
    output [7:0] q;

    assign q[0] = clk;
    assign q[1] = d;
    assign q[2] = clk & d;
    assign q[3] = clk | d;
    assign q[4] = clk ^ d;
    assign q[5] = ~(clk);
    assign q[6] = ~(q[3]);
    assign q[7] = clk & ~d;

endmodule

module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input				brstn   ,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

	reg [3:0] q;

	always @(posedge clk_a or posedge clk_b or posedge arstn or posedge brstn or posedge data_en) begin
		if (data_en)
			q[0] <= clk_b;
		else
			q[0] <= data_in[0];

		q[1] <= arstn;
		q[2] <= brstn;
		q[3] <= data_in[3];
	end

	assign dataout = q;

endmodule

module fsm(IN, MATCH, CLK, RST);
input IN, CLK, RST;
output reg MATCH;

// Internal signals
wire dff0_q, dff1_q, dff2_q;
wire and1_out, and2_out, and3_out, and4_out;
wire or1_out, or2_out, or3_out;
wire not1_out;

// Logic gates and flip-flops
assign not1_out = ~CLK;

assign and1_out = IN & RST;
assign and2_out = and1_out & dff0_q;
assign and3_out = and2_out & not1_out;

assign or1_out = dff0_q | dff1_q;
assign or2_out = or1_out | and3_out;

assign and4_out = CLK & dff2_q;
assign or3_out = or2_out | and4_out;

always @(posedge IN)
begin
    dff0_q <= and1_out;
    dff1_q <= or1_out;
    dff2_q <= and4_out;
end

always @(posedge IN)
begin
    MATCH <= or3_out;
end

endmodule

module parallel2serial(
    input clk,
    input rst_n,
    input [3:0] d,
    output valid_out,
    output dout
);
    wire n1, n2, n3, n4, n5, n6, n7;

    reg dff1_q, dff2_q, dff3_q, dff4_q, dff5_q, dff6_q;

    // Flip-Flop 1
    always @(posedge clk)
        dff1_q <= rst_n;

    // Flip-Flop 2
    always @(posedge clk)
        dff2_q <= n1;

    // Flip-Flop 3
    always @(posedge clk)
        dff3_q <= n3;

    // Flip-Flop 4
    always @(posedge clk)
        dff4_q <= dff3_q;

    // Flip-Flop 5
    always @(posedge clk)
        dff5_q <= n5;

    // Flip-Flop 6
    always @(posedge clk)
        dff6_q <= n7;

    // Logic gates
    assign n1 = rst_n & dff1_q;
    assign n2 = d[0] | d[1];
    assign n3 = n2 & dff2_q;
    assign n4 = d[2] ^ d[3];
    assign n5 = n3 & n4;
    assign n6 = dff4_q | dff5_q;
    assign n7 = n6 & ~rst_n;

    // Outputs
    assign valid_out = dff6_q & clk;
    assign dout = ~dff5_q;
endmodule

module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );

wire dff0_q, dff1_q, and0_out, and1_out, not0_out, not1_out, or0_out;

// NOT gates
assign not0_out = ~rst_n;
assign not1_out = ~dff0_q;

// AND gates
assign and0_out = clk & data_in;
assign and1_out = dff1_q & not1_out;

// OR gate
assign or0_out = and1_out | not0_out;

// D Flip-Flops
S_DFF_PN0 dff0 (
    .C(clk),
    .R(data_in),
    .D(and0_out),
    .Q(dff0_q)
);

S_DFF_PN1 dff1 (
    .C(clk),
    .R(data_in),
    .D(or0_out),
    .Q(dff1_q)
);

// Final output
assign sequence_detected = dff0_q & dff1_q;

endmodule
